// Package ledger renders ledger entries as a formatted table.
package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Refactoring log
//
// The original implementation passed the test suite but was hard to follow.
// It was rewritten in the following steps, with the test suite run after
// each step:
//
//  1. The recursive call that validated the currency for an empty entry
//     list was replaced by an up-front currency check, which covers both
//     the empty and non-empty cases.
//  2. The hand-rolled selection sort (with its m1/m2 maps) was replaced
//     by sort.SliceStable over a copy of the entries; the input slice is
//     still not modified.
//  3. The goroutine-per-entry plus channel fan-out was replaced by a plain
//     sequential loop that builds the output in a strings.Builder.
//  4. The locale-specific header, date and amount formatting was extracted
//     into a locale type with function fields.
//  5. The manual digit padding and string slicing was replaced by
//     arithmetic (dollars = cents/100, frac = cents%100) and a
//     groupThousands helper.
//  6. The empty error values were given real messages.

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

var (
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidDate     = errors.New("invalid date")
)

// Column widths of the rendered table.
const (
	dateWidth   = 10
	descWidth   = 25
	changeWidth = 13
)

// locale describes how the table is rendered for a particular locale.
type locale struct {
	dateHeader   string
	descHeader   string
	changeHeader string
	formatDate   func(date string) (string, error)
	formatAmount func(symbol string, cents int) string
}

var locales = map[string]locale{
	"en-US": {
		dateHeader:   "Date",
		descHeader:   "Description",
		changeHeader: "Change",
		formatDate: func(date string) (string, error) {
			if !validDate(date) {
				return "", errInvalidDate
			}
			return date[5:7] + "/" + date[8:10] + "/" + date[0:4], nil
		},
		formatAmount: func(symbol string, cents int) string {
			if cents < 0 {
				return "(" + symbol + number(-cents, ",", ".") + ")"
			}
			return symbol + number(cents, ",", ".") + " "
		},
	},
	"nl-NL": {
		dateHeader:   "Datum",
		descHeader:   "Omschrijving",
		changeHeader: "Verandering",
		formatDate: func(date string) (string, error) {
			if !validDate(date) {
				return "", errInvalidDate
			}
			return date[8:10] + "-" + date[5:7] + "-" + date[0:4], nil
		},
		formatAmount: func(symbol string, cents int) string {
			if cents < 0 {
				return symbol + " " + number(-cents, ".", ",") + "-"
			}
			return symbol + " " + number(cents, ".", ",") + " "
		},
	},
}

// FormatLedger renders the given entries as a formatted ledger table for the
// given currency (USD or EUR) and locale (en-US or nl-NL). The entries are
// sorted by date, then description, then change; the input slice is not
// modified.
func FormatLedger(currency string, localeName string, entries []Entry) (string, error) {
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	loc, ok := locales[localeName]
	if !ok {
		return "", errInvalidLocale
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(loc.header())
	for _, e := range sorted {
		line, err := loc.line(symbol, e)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// header renders the table's header row.
func (l locale) header() string {
	return padRight(l.dateHeader, dateWidth) + " | " +
		padRight(l.descHeader, descWidth) + " | " +
		l.changeHeader + "\n"
}

// line renders a single entry as a table row.
func (l locale) line(symbol string, e Entry) (string, error) {
	date, err := l.formatDate(e.Date)
	if err != nil {
		return "", err
	}
	return padRight(date, dateWidth) + " | " +
		formatDescription(e.Description) + " | " +
		padLeftRune(l.formatAmount(symbol, e.Change), changeWidth) + "\n"
}

// currencySymbol maps a currency code to its symbol.
func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	}
	return "", errInvalidCurrency
}

// validDate reports whether date has the expected "YYYY-MM-DD" shape.
func validDate(date string) bool {
	return len(date) == 10 && date[4] == '-' && date[7] == '-'
}

// formatDescription truncates descriptions longer than descWidth bytes to
// descWidth-3 bytes plus an ellipsis, and pads shorter ones with spaces.
func formatDescription(desc string) string {
	if len(desc) > descWidth {
		return desc[:descWidth-3] + "..."
	}
	return padRight(desc, descWidth)
}

// number renders the absolute value of an amount in cents as a plain number
// with the given thousands and decimal separators, e.g. 123456 -> "1.234,56".
func number(cents int, groupSep, decimalSep string) string {
	dollars, frac := cents/100, cents%100
	return groupThousands(strconv.Itoa(dollars), groupSep) + decimalSep + fmt.Sprintf("%02d", frac)
}

// groupThousands inserts groupSep every three digits from the right,
// e.g. "1234567" -> "1,234,567".
func groupThousands(digits, groupSep string) string {
	var groups []string
	for len(digits) > 3 {
		groups = append(groups, digits[len(digits)-3:])
		digits = digits[:len(digits)-3]
	}
	groups = append(groups, digits)
	for i, j := 0, len(groups)-1; i < j; i, j = i+1, j-1 {
		groups[i], groups[j] = groups[j], groups[i]
	}
	return strings.Join(groups, groupSep)
}

// padRight pads s with spaces on the right until it reaches width w bytes.
func padRight(s string, w int) string {
	return s + strings.Repeat(" ", w-len(s))
}

// padLeftRune right-justifies s in a field of width w, counting the width in
// runes so that multi-byte characters such as "€" keep the original
// alignment.
func padLeftRune(s string, w int) string {
